/* Physics Laboratory — centralized equation models and interactive tools. */
const CATS=['Kinematics','Circular motion & rotation','Dynamics','Work, energy & power','Momentum & collisions','Rotational inertia & rolling','Properties of matter','Fluid mechanics','Thermodynamics','Waves & oscillations','Electricity','Magnetism','Gravitation & space','Modern physics'];
const D={};
function add(cat,name,eq,vars,unit,desc,sol,conditions,type='model',mistake='Check units and signs before substituting.'){D[name]={cat,name,eq,vars,unit,desc,sol,conditions,type,mistake};}
const M='Use consistent SI units; state the positive direction before assigning signs.';
const K='For constant acceleration in an inertial frame; choose a positive direction. Neglect air resistance where stated.';
// Kinematics
add('Kinematics','Distance at constant speed','d = vt',['d','v','t'],'m','Distance traveled at constant speed.',{d:'v*t',v:'d/t',t:'d/v'},'Speed is constant; distance is non-negative.','linear');
add('Kinematics','Average speed','v_avg = d_total / t_total',['v_avg','d_total','t_total'],'m/s','Total path length divided by elapsed time.',{v_avg:'d_total/t_total',d_total:'v_avg*t_total',t_total:'d_total/v_avg'},'Use total distance, not displacement.','linear','Speed is scalar; do not substitute a signed displacement.');
add('Kinematics','Average velocity','v_avg = Δx / Δt',['v_avg','dx','dt'],'m/s','Displacement divided by elapsed time.',{v_avg:'dx/dt',dx:'v_avg*dt',dt:'dx/v_avg'},'Velocity is signed along the chosen axis.','linear');
add('Kinematics','Acceleration','a = (v − u) / t',['a','v','u','t'],'m/s²','Change in velocity per unit time.',{a:'(v-u)/t',v:'u+a*t',u:'v-a*t',t:'(v-u)/a'},'Average acceleration; t > 0.','linear');
add('Kinematics','First equation of motion','v = u + at',['v','u','a','t'],'m/s','Final velocity after constant acceleration.',{v:'u+a*t',u:'v-a*t',a:'(v-u)/t',t:'(v-u)/a'},K,'linear');
add('Kinematics','Second equation of motion','s = ut + ½at²',['s','u','a','t'],'m','Displacement under constant acceleration.',{s:'u*t+0.5*a*t*t',u:'(s-0.5*a*t*t)/t',a:'2*(s-u*t)/(t*t)',t:'(-u+sqrt(u*u+2*a*s))/a'},K,'quadratic');
add('Kinematics','Third equation of motion','v² = u² + 2as',['v','u','a','s'],'m/s','Relates velocity and displacement without time.',{v:'sqrt(u*u+2*a*s)',u:'sqrt(v*v-2*a*s)',a:'(v*v-u*u)/(2*s)',s:'(v*v-u*u)/(2*a)'},K+' Select the velocity sign from the direction of motion.','quadratic');
add('Kinematics','Displacement from mean velocity','s = ½(u + v)t',['s','u','v','t'],'m','Displacement for constant acceleration using mean velocity.',{s:'0.5*(u+v)*t',u:'2*s/t-v',v:'2*s/t-u',t:'2*s/(u+v)'},K,'linear');
add('Kinematics','Free-fall velocity','v = u + gt',['v','u','g','t'],'m/s','Vertical velocity with positive direction chosen downward.',{v:'u+g*t',u:'v-g*t',g:'(v-u)/t',t:'(v-u)/g'},'Constant gravitational field; downward-positive convention in this displayed form.','linear');
add('Kinematics','Free-fall displacement','h = ut + ½gt²',['h','u','g','t'],'m','Vertical displacement with positive direction downward.',{h:'u*t+0.5*g*t*t',u:'(h-0.5*g*t*t)/t',g:'2*(h-u*t)/(t*t)',t:'(-u+sqrt(u*u+2*g*h))/g'},'Uniform gravity; downward-positive convention.','quadratic');
add('Kinematics','Projectile time of flight','T = 2u sin θ / g',['T','u','theta','g'],'s','Flight time when launch and landing heights are equal.',{T:'2*u*sin(theta)/g',u:'T*g/(2*sin(theta))',g:'2*u*sin(theta)/T',theta:'asin(T*g/(2*u))'},'Same launch and landing height; negligible air resistance; angle in degrees.','sinusoidal');
add('Kinematics','Maximum projectile height','H = u² sin² θ / 2g',['H','u','theta','g'],'m','Maximum rise above launch point.',{H:'u*u*sin(theta)**2/(2*g)',u:'sqrt(2*g*H)/sin(theta)',g:'u*u*sin(theta)**2/(2*H)',theta:'asin(sqrt(2*g*H)/u)'},'Negligible air resistance; level uniform gravity; angle in degrees.','quadratic');
add('Kinematics','Projectile range','R = u² sin(2θ) / g',['R','u','theta','g'],'m','Horizontal range for equal launch and landing heights.',{R:'u*u*sin(2*theta)/g',u:'sqrt(R*g/sin(2*theta))',g:'u*u*sin(2*theta)/R',theta:'0.5*asin(R*g/(u*u))'},'Same launch and landing height; negligible air resistance. Angle in degrees.','sinusoidal');
add('Kinematics','Projectile horizontal position','x = u cos θ · t',['x','u','theta','t'],'m','Horizontal displacement for a projectile.',{x:'u*cos(theta)*t',u:'x/(cos(theta)*t)',theta:'acos(x/(u*t))',t:'x/(u*cos(theta))'},'Negligible air resistance; horizontal acceleration is zero. Angle in degrees.','linear');
// Rotational motion
add('Circular motion & rotation','Angular displacement','θ = s / r',['theta','s','r'],'rad','Angle swept out by an arc.',{theta:'s/r',s:'theta*r',r:'s/theta'},'Radians; fixed axis and circular path.','linear');
add('Circular motion & rotation','Angular velocity','ω = Δθ / t',['omega','theta','t'],'rad/s','Angular displacement per elapsed time.',{omega:'theta/t',theta:'omega*t',t:'theta/omega'},'Average angular velocity; use radians.','linear');
add('Circular motion & rotation','Angular acceleration','α = (ω − ω₀) / t',['alpha','omega','omega0','t'],'rad/s²','Change in angular velocity per time.',{alpha:'(omega-omega0)/t',omega:'omega0+alpha*t',omega0:'omega-alpha*t',t:'(omega-omega0)/alpha'},'Average angular acceleration; fixed axis.','linear');
add('Circular motion & rotation','Linear speed from angular speed','v = rω',['v','r','omega'],'m/s','Tangential speed for rotation about an axis.',{v:'r*omega',r:'v/omega',omega:'v/r'},'Rigid-body rotation about a fixed axis.','linear');
add('Circular motion & rotation','Centripetal acceleration','a_c = v² / r',['ac','v','r'],'m/s²','Inward acceleration for circular motion.',{ac:'v*v/r',v:'sqrt(ac*r)',r:'v*v/ac'},'Magnitude points toward the center; not an extra force.','quadratic');
add('Circular motion & rotation','Centripetal acceleration (ω)','a_c = rω²',['ac','r','omega'],'m/s²','Centripetal acceleration from angular speed.',{ac:'r*omega*omega',r:'ac/(omega*omega)',omega:'sqrt(ac/r)'},'Magnitude points toward the center.','quadratic');
add('Circular motion & rotation','Centripetal force','F_c = mv² / r',['Fc','m','v','r'],'N','Net inward force required for circular motion.',{Fc:'m*v*v/r',m:'Fc*r/(v*v)',v:'sqrt(Fc*r/m)',r:'m*v*v/Fc'},'Net inward force, supplied by real forces; circular path.','quadratic');
add('Circular motion & rotation','Period from angular speed','T = 2π / ω',['T','omega'],'s','Time for one revolution.',{T:'2*pi/omega',omega:'2*pi/T'},'Periodic rotation; ω in rad/s.','inverse');
add('Circular motion & rotation','Frequency from period','f = 1 / T',['f','T'],'Hz','Cycles per second.',{f:'1/T',T:'1/f'},'T > 0.','inverse');
add('Circular motion & rotation','Angular speed from frequency','ω = 2πf',['omega','f'],'rad/s','Angular speed for periodic motion.',{omega:'2*pi*f',f:'omega/(2*pi)'},'One full cycle is 2π radians.','linear');
add('Circular motion & rotation','Rotational kinematics','ω = ω₀ + αt',['omega','omega0','alpha','t'],'rad/s','Angular velocity under constant angular acceleration.',{omega:'omega0+alpha*t',omega0:'omega-alpha*t',alpha:'(omega-omega0)/t',t:'(omega-omega0)/alpha'},'Fixed axis; constant angular acceleration.','linear');
add('Circular motion & rotation','Angular displacement (constant α)','θ = ω₀t + ½αt²',['theta','omega0','alpha','t'],'rad','Angular displacement under constant angular acceleration.',{theta:'omega0*t+0.5*alpha*t*t',omega0:'(theta-0.5*alpha*t*t)/t',alpha:'2*(theta-omega0*t)/(t*t)',t:'(-omega0+sqrt(omega0*omega0+2*alpha*theta))/alpha'},'Fixed axis; constant angular acceleration.','quadratic');
add('Circular motion & rotation','Rotational kinetic energy','K_rot = ½Iω²',['K','I','omega'],'J','Kinetic energy of rotation about an axis.',{K:'0.5*I*omega*omega',I:'2*K/(omega*omega)',omega:'sqrt(2*K/I)'},'Rigid body rotating about a fixed axis.','quadratic');
add('Circular motion & rotation','Torque magnitude','τ = rF sin θ',['tau','r','F','theta'],'N·m','Magnitude of torque from a force.',{tau:'r*F*sin(theta)',r:'tau/(F*sin(theta))',F:'tau/(r*sin(theta))',theta:'asin(tau/(r*F))'},'θ is between lever arm and force; angle in degrees.','sinusoidal');
add('Circular motion & rotation','Rotational Newton’s second law','τ_net = Iα',['tau','I','alpha'],'N·m','Net torque for fixed-axis rotation.',{tau:'I*alpha',I:'tau/alpha',alpha:'tau/I'},'Fixed axis and constant moment of inertia.','linear');
add('Circular motion & rotation','Angular momentum','L = Iω',['L','I','omega'],'kg·m²/s','Angular momentum for a rigid body around a fixed axis.',{L:'I*omega',I:'L/omega',omega:'L/I'},'Fixed axis; sign follows the rotation direction.','linear');
add('Circular motion & rotation','Angular momentum conservation','I₁ω₁ = I₂ω₂',['I1','omega1','I2','omega2'],'kg·m²/s','Relates rotational states when external torque is negligible.',{I1:'I2*omega2/omega1',omega1:'I2*omega2/I1',I2:'I1*omega1/omega2',omega2:'I1*omega1/I2'},'Zero net external torque about the axis.','inverse');
// Dynamics
add('Dynamics','Newton’s second law','F_net = ma',['F','m','a'],'N','Net force equals mass times acceleration.',{F:'m*a',m:'F/a',a:'F/m'},'Inertial frame; F is the vector sum along the chosen axis.','linear');
add('Dynamics','Weight','W = mg',['W','m','g'],'N','Gravitational force near a planetary surface.',{W:'m*g',m:'W/g',g:'W/m'},'Uniform local gravitational field.','linear');
add('Dynamics','Kinetic friction','f_k = μ_k N',['f','mu','N'],'N','Magnitude of kinetic friction.',{f:'mu*N',mu:'f/N',N:'f/mu'},'Surfaces slide; N is the actual normal force.','linear','Kinetic friction opposes relative sliding; do not substitute static friction.');
add('Dynamics','Maximum static friction','f_s,max = μ_s N',['fs','mu','N'],'N','Upper limit of static friction magnitude.',{fs:'mu*N',mu:'fs/N',N:'fs/mu'},'At impending slip; actual static friction may be smaller.','linear');
add('Dynamics','Hooke’s law','F_s = −kx',['F','k','x'],'N','Restoring force of an ideal spring.',{F:'-k*x',k:'-F/x',x:'-F/k'},'Linear elastic regime; x measured from equilibrium.','linear');
add('Dynamics','Incline force component','F∥ = mg sin θ',['Fpar','m','g','theta'],'N','Component of weight parallel to a simple incline.',{Fpar:'m*g*sin(theta)',m:'Fpar/(g*sin(theta))',g:'Fpar/(m*sin(theta))',theta:'asin(Fpar/(m*g))'},'θ measured from horizontal; angle in degrees.','sinusoidal');
add('Dynamics','Incline normal force','N = mg cos θ',['N','m','g','theta'],'N','Normal force on a simple incline without other perpendicular forces.',{N:'m*g*cos(theta)',m:'N/(g*cos(theta))',g:'N/(m*cos(theta))',theta:'acos(N/(m*g))'},'Simple incline; no other forces normal to surface. Angle in degrees.','sinusoidal');
add('Dynamics','Universal gravitation','F = Gm₁m₂/r²',['F','G','m1','m2','r'],'N','Gravitational attraction between two masses.',{F:'G*m1*m2/(r*r)',G:'F*r*r/(m1*m2)',m1:'F*r*r/(G*m2)',m2:'F*r*r/(G*m1)',r:'sqrt(G*m1*m2/F)'},'Point masses or spherical bodies; r between centers. G = 6.67430×10⁻¹¹ N·m²/kg².','inverse square');
add('Dynamics','Gravitational field strength','g = GM/r²',['g','G','M','r'],'m/s²','Field magnitude outside a spherical body.',{g:'G*M/(r*r)',G:'g*r*r/M',M:'g*r*r/G',r:'sqrt(G*M/g)'},'Spherical symmetry or point mass; radius from center.','inverse square');
add('Dynamics','Elevator apparent weight','N = m(g + a)',['N','m','g','a'],'N','Normal force for upward-positive elevator acceleration.',{N:'m*(g+a)',m:'N/(g+a)',g:'N/m-a',a:'N/m-g'},'Positive a is upward; free-body diagram required.','linear');
add('Dynamics','Elevator apparent weight (downward a)','N = m(g − a)',['N','m','g','a'],'N','Normal force for downward elevator acceleration magnitude.',{N:'m*(g-a)',m:'N/(g-a)',g:'N/m+a',a:'g-N/m'},'a is a nonnegative downward magnitude; N cannot be negative in contact.','linear');
// Work and energy
add('Work, energy & power','Work by constant force','W = Fd cos θ',['W','F','d','theta'],'J','Work by a constant force over a displacement.',{W:'F*d*cos(theta)',F:'W/(d*cos(theta))',d:'W/(F*cos(theta))',theta:'acos(W/(F*d))'},'θ between force and displacement; angle in degrees.','sinusoidal');
add('Work, energy & power','Kinetic energy','K = ½mv²',['K','m','v'],'J','Translational kinetic energy.',{K:'0.5*m*v*v',m:'2*K/(v*v)',v:'sqrt(2*K/m)'},'Classical speeds much less than c.','quadratic');
add('Work, energy & power','Gravitational potential energy','U = mgh',['U','m','g','h'],'J','Near-surface gravitational potential energy relative to a reference height.',{U:'m*g*h',m:'U/(g*h)',g:'U/(m*h)',h:'U/(m*g)'},'Uniform g; specify the zero-height reference.','linear');
add('Work, energy & power','Elastic potential energy','U_s = ½kx²',['U','k','x'],'J','Energy stored in an ideal spring.',{U:'0.5*k*x*x',k:'2*U/(x*x)',x:'sqrt(2*U/k)'},'Spring obeys Hooke’s law.','quadratic');
add('Work, energy & power','Mechanical energy','E = K + U',['E','K','U'],'J','Sum of kinetic and potential energy.',{E:'K+U',K:'E-U',U:'E-K'},'Potential energy reference must be defined.','linear');
add('Work, energy & power','Work-energy theorem','W_net = ΔK',['W','K2','K1'],'J','Net work equals change in kinetic energy.',{W:'K2-K1',K2:'W+K1',K1:'K2-W'},'Work by all forces; classical mechanics.','linear');
add('Work, energy & power','Mechanical energy conservation','K₁ + U₁ = K₂ + U₂',['K1','U1','K2','U2'],'J','Relates initial and final mechanical energy.',{K1:'K2+U2-U1',U1:'K2+U2-K1',K2:'K1+U1-U2',U2:'K1+U1-K2'},'Only conservative forces do work, or nonconservative work is negligible.','linear');
add('Work, energy & power','Average power','P = W / t',['P','W','t'],'W','Work transferred per unit time.',{P:'W/t',W:'P*t',t:'W/P'},'Average power over the interval.','linear');
add('Work, energy & power','Instantaneous power','P = Fv cos θ',['P','F','v','theta'],'W','Power delivered by force to an object moving at velocity v.',{P:'F*v*cos(theta)',F:'P/(v*cos(theta))',v:'P/(F*cos(theta))',theta:'acos(P/(F*v))'},'θ between force and velocity.','sinusoidal');
add('Work, energy & power','Efficiency','η = E_out / E_in × 100%',['eta','Eout','Ein'],'%','Fraction of input energy delivered usefully.',{eta:'100*Eout/Ein',Eout:'eta*Ein/100',Ein:'100*Eout/eta'},'Input energy > 0; real device efficiency is at most 100%.','linear');
// Momentum
add('Momentum & collisions','Linear momentum','p = mv',['p','m','v'],'kg·m/s','Linear momentum along a chosen axis.',{p:'m*v',m:'p/v',v:'p/m'},'Signed velocity is required for one-dimensional motion.','linear');
add('Momentum & collisions','Impulse','J = FΔt',['J','F','dt'],'N·s','Impulse from a constant force over time.',{J:'F*dt',F:'J/dt',dt:'J/F'},'For varying force use impulse as the area under the force-time curve.','linear');
add('Momentum & collisions','Impulse-momentum theorem','J = Δp',['J','p2','p1'],'N·s','Impulse equals momentum change.',{J:'p2-p1',p2:'J+p1',p1:'p2-J'},'Net impulse; vector components treated separately.','linear');
add('Momentum & collisions','Momentum conservation (two bodies)','m₁u₁ + m₂u₂ = m₁v₁ + m₂v₂',['m1','u1','m2','u2','v1','v2'],'kg·m/s','One-dimensional momentum balance before and after interaction.',{v1:'(m1*u1+m2*u2-m2*v2)/m1',v2:'(m1*u1+m2*u2-m1*v1)/m2',u1:'(m1*v1+m2*v2-m2*u2)/m1',u2:'(m1*v1+m2*v2-m1*u1)/m2',m1:'m2*(v2-u2)/(u1-v1)',m2:'m1*(u1-v1)/(v2-u2)'},'Zero net external impulse; assign a consistent axis and signs.','linear');
add('Momentum & collisions','Coefficient of restitution','e = (v₂ − v₁)/(u₁ − u₂)',['e','v2','v1','u1','u2'],'dimensionless','Relative separation speed divided by relative approach speed.',{e:'(v2-v1)/(u1-u2)',v2:'e*(u1-u2)+v1',v1:'v2-e*(u1-u2)',u1:'(v2-v1)/e+u2',u2:'u1-(v2-v1)/e'},'One-dimensional impact; labels preserve pre/post collision convention.','linear');
add('Momentum & collisions','Perfectly inelastic collision','v = (m₁u₁ + m₂u₂)/(m₁ + m₂)',['v','m1','u1','m2','u2'],'m/s','Shared final velocity when two bodies stick together.',{v:'(m1*u1+m2*u2)/(m1+m2)',m1:'m2*(v-u2)/(u1-v)',u1:'(v*(m1+m2)-m2*u2)/m1',m2:'m1*(u1-v)/(v-u2)',u2:'(v*(m1+m2)-m1*u1)/m2'},'One-dimensional; zero external impulse; bodies move together afterward.','linear');
// Rotational inertia and rolling
add('Rotational inertia & rolling','Moment of inertia (particles)','I = Σmr²',['I','m','r'],'kg·m²','Rotational inertia for point masses at a common radius.',{I:'m*r*r',m:'I/(r*r)',r:'sqrt(I/m)'},'For a system, sum each mᵢrᵢ² about the stated axis.','quadratic');
add('Rotational inertia & rolling','Solid sphere moment of inertia','I = ⅖MR²',['I','M','R'],'kg·m²','Moment of inertia of a uniform solid sphere about a diameter.',{I:'0.4*M*R*R',M:'I/(0.4*R*R)',R:'sqrt(I/(0.4*M))'},'Uniform solid sphere; axis through center.','quadratic');
add('Rotational inertia & rolling','Solid cylinder moment of inertia','I = ½MR²',['I','M','R'],'kg·m²','Moment of inertia of a uniform solid cylinder about central symmetry axis.',{I:'0.5*M*R*R',M:'2*I/(R*R)',R:'sqrt(2*I/M)'},'Uniform solid cylinder about its symmetry axis.','quadratic');
add('Rotational inertia & rolling','Thin hoop moment of inertia','I = MR²',['I','M','R'],'kg·m²','Moment of inertia of a thin hoop about central axis.',{I:'M*R*R',M:'I/(R*R)',R:'sqrt(I/M)'},'Thin hoop about axis through center perpendicular to plane.','quadratic');
add('Rotational inertia & rolling','Solid disk moment of inertia','I = ½MR²',['I','M','R'],'kg·m²','Moment of inertia of a uniform disk about central axis.',{I:'0.5*M*R*R',M:'2*I/(R*R)',R:'sqrt(2*I/M)'},'Uniform solid disk about central axis.','quadratic');
add('Rotational inertia & rolling','Thin rod about center','I = ML² / 12',['I','M','L'],'kg·m²','Moment of inertia of a uniform thin rod about center, perpendicular to length.',{I:'M*L*L/12',M:'12*I/(L*L)',L:'sqrt(12*I/M)'},'Uniform thin rod; central perpendicular axis.','quadratic');
add('Rotational inertia & rolling','Thin rod about end','I = ML² / 3',['I','M','L'],'kg·m²','Moment of inertia of a uniform thin rod about one end.',{I:'M*L*L/3',M:'3*I/(L*L)',L:'sqrt(3*I/M)'},'Uniform thin rod; perpendicular axis through end.','quadratic');
add('Rotational inertia & rolling','Parallel-axis theorem','I = I_cm + Md²',['I','Icm','M','d'],'kg·m²','Moment of inertia about an axis parallel to the center-of-mass axis.',{I:'Icm+M*d*d',Icm:'I-M*d*d',M:'(I-Icm)/(d*d)',d:'sqrt((I-Icm)/M)'},'Axes are parallel; one passes through center of mass.','quadratic');
add('Rotational inertia & rolling','Rolling without slipping','v_cm = Rω',['v','R','omega'],'m/s','Translational and angular speeds for pure rolling.',{v:'R*omega',R:'v/omega',omega:'v/R'},'No slip at contact point.','linear');
add('Rotational inertia & rolling','Total rolling kinetic energy','K = ½Mv² + ½Iω²',['K','M','v','I','omega'],'J','Translational plus rotational kinetic energy.',{K:'0.5*M*v*v+0.5*I*omega*omega',M:'(2*K-I*omega*omega)/(v*v)',v:'sqrt((2*K-I*omega*omega)/M)',I:'(2*K-M*v*v)/(omega*omega)',omega:'sqrt((2*K-M*v*v)/I)'},'Rigid body; include rotation about center of mass.','quadratic');
add('Rotational inertia & rolling','Rolling down an incline','a = g sin θ / [1 + I/(mR²)]',['a','g','theta','I','m','R'],'m/s²','Acceleration of a rigid body rolling without slipping down a fixed incline.',{a:'g*sin(theta)/(1+I/(m*R*R))',g:'a*(1+I/(m*R*R))/sin(theta)',theta:'asin(a*(1+I/(m*R*R))/g)',I:'m*R*R*(g*sin(theta)/a-1)',m:'I/(R*R*(g*sin(theta)/a-1))',R:'sqrt(I/(m*(g*sin(theta)/a-1)))'},'Rigid body; static friction sufficient; no slip; angle in degrees.','sinusoidal');
// Matter / fluids
add('Properties of matter','Density','ρ = m / V',['rho','m','V'],'kg/m³','Mass per unit volume.',{rho:'m/V',m:'rho*V',V:'m/rho'},'Use consistent units; density may vary with temperature and pressure.','inverse');
add('Properties of matter','Relative density','RD = ρ / ρ_ref',['RD','rho','rhoref'],'dimensionless','Density relative to a reference material.',{RD:'rho/rhoref',rho:'RD*rhoref',rhoref:'rho/RD'},'Reference often water for liquids and solids; ratio has no units.','linear');
add('Properties of matter','Average density','ρ_avg = m_total / V_total',['rho','m','V'],'kg/m³','Total mass divided by total volume.',{rho:'m/V',m:'rho*V',V:'m/rho'},'Use external volume including internal voids when describing bulk density.','inverse');
add('Fluid mechanics','Pressure','P = F / A',['P','F','A'],'Pa','Normal force per area.',{P:'F/A',F:'P*A',A:'F/P'},'Force component perpendicular to area.','inverse');
add('Fluid mechanics','Hydrostatic gauge pressure','P = ρgh',['P','rho','g','h'],'Pa','Pressure increase with depth in a static fluid.',{P:'rho*g*h',rho:'P/(g*h)',g:'P/(rho*h)',h:'P/(rho*g)'},'Fluid at rest; uniform density; h is vertical depth.','linear');
add('Fluid mechanics','Absolute fluid pressure','P_abs = P_atm + ρgh',['P','Patm','rho','g','h'],'Pa','Absolute pressure at depth below an open surface.',{P:'Patm+rho*g*h',Patm:'P-rho*g*h',rho:'(P-Patm)/(g*h)',g:'(P-Patm)/(rho*h)',h:'(P-Patm)/(rho*g)'},'Static fluid open to atmosphere at the surface.','linear');
add('Fluid mechanics','Hydraulic press','F₁/A₁ = F₂/A₂',['F1','A1','F2','A2'],'N or m²','Ideal force transmission in a hydraulic system.',{F1:'F2*A1/A2',A1:'F1*A2/F2',F2:'F1*A2/A1',A2:'F2*A1/F1'},'Pascal principle; ideal incompressible fluid, equal pressure change.','linear');
add('Fluid mechanics','Buoyant force','F_b = ρ_fluid g V_displaced',['Fb','rho','g','V'],'N','Upward force equal to weight of displaced fluid.',{Fb:'rho*g*V',rho:'Fb/(g*V)',g:'Fb/(rho*V)',V:'Fb/(rho*g)'},'Use displaced fluid volume, not necessarily object volume.','linear');
add('Fluid mechanics','Apparent weight','W_app = W − F_b',['Wapp','W','Fb'],'N','Weight measured while immersed in fluid.',{Wapp:'W-Fb',W:'Wapp+Fb',Fb:'W-Wapp'},'Buoyancy opposes weight for a submerged object.','linear');
