function openModal(html){document.getElementById('modal-content').innerHTML=html;document.getElementById('modal').classList.remove('hidden')}function closeModal(){document.getElementById('modal').classList.add('hidden')}document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);
function openFormula(name){const f=D[name];if(!f)return;const opts=Object.keys(f.sol);let target=opts[0],fixed=f.vars.filter(v=>v!==target);const html=`<div class="modal-content-head"><div class="eyebrow">${f.cat.toUpperCase()} · ${f.unit}</div><h2 id="modal-title">${f.name}</h2><div class="modal-eq">${f.eq}</div><p class="modal-desc">${f.desc}</p></div><div class="modal-grid"><div class="subpanel"><h3>INTERACTIVE CALCULATOR</h3><label class="field-label">SOLVE FOR<select id="calc-target" class="modal-select">${opts.map(v=>`<option value="${v}">${label(v)} (${v}) · ${unitFor(f,v)}</option>`).join('')}</select></label><div class="variable-inputs" id="calc-inputs"></div><div class="calc-result" id="calc-result"></div></div><div class="subpanel"><h3>MODEL CONDITIONS</h3><ul class="condition-list">${f.conditions.split(';').map(s=>`<li>${s.trim()}</li>`).join('')}</ul><p class="mistake">Common mistake: ${f.mistake}</p><h3 style="margin-top:17px">SYMBOLS & SI UNITS</h3><ul class="condition-list">${f.vars.map(v=>`<li><b>${v}</b> — ${label(v)} <span style="color:#7c91aa">(${unitFor(f,v)})</span></li>`).join('')}</ul></div><div class="subpanel"><h3>WORKED EXAMPLES</h3><div class="example-list" id="example-list"></div></div><div class="subpanel"><h3>RELATED RELATIONSHIPS</h3><div class="example-list">${all.filter(x=>x.cat===f.cat&&x.name!==f.name).slice(0,4).map(x=>`<div class="example" data-related="${x.name}"><b>${x.name}</b><p>${x.eq}</p></div>`).join('')||'<p class="modal-desc">Browse another topic in the library.</p>'}</div></div></div>`;openModal(html);const calc=()=>{target=document.getElementById('calc-target').value;fixed=f.vars.filter(v=>v!==target);document.getElementById('calc-inputs').innerHTML=fixed.map(v=>`<div class="var-field"><label>${label(v)} (${v}) · ${unitFor(f,v)}</label><input type="number" step="any" id="val-${v}" placeholder="Enter ${v}"></div>`).join('');document.querySelectorAll('#calc-inputs input').forEach(i=>i.oninput=updateCalc);updateCalc();renderExamples(f,target)};const updateCalc=()=>{const values={};for(const v of fixed){const raw=document.getElementById('val-'+v)?.value;if(raw===''||raw==null){document.getElementById('calc-result').innerHTML='<small>ENTER KNOWN VALUES</small>';return}values[v]=Number(raw)}let result;try{result=evaluate(f.sol[target],values)}catch{result=NaN}const box=document.getElementById('calc-result');if(!Number.isFinite(result)){box.innerHTML='<small>RESULT UNDEFINED</small><div class="steps">Check for division by zero, invalid square roots, logarithms, or a physically inconsistent input.</div>';return}const rounded=sig(result,4);const subs=f.sol[target].replaceAll('**','^');box.innerHTML=`<small>CALCULATED ${target.toUpperCase()}</small><strong>${rounded} <small>${unitFor(f,target)}</small></strong><div class="steps">${target} = ${subs}<br>${target} = ${Object.entries(values).map(([k,v])=>`${k}:${v}`).join(' · ')}<br><b>Result: ${rounded} ${f.unit}</b></div>`};document.getElementById('calc-target').onchange=calc;calc();document.querySelectorAll('[data-related]').forEach(x=>x.onclick=()=>openFormula(x.dataset.related));}
function sig(x,n=4){if(!Number.isFinite(x))return 'undefined';if(x===0)return '0';return Number(x.toPrecision(n)).toString()}
