document.getElementById('sim-tabs').innerHTML=sims.map((s,i)=>`<button class="sim-tab ${i===0?'selected':''}" data-sim="${s.id}">${s.name}</button>`).join('');document.querySelectorAll('[data-sim]').forEach(b=>b.onclick=()=>selectSim(b.dataset.sim));
function selectSim(id){activeSim=sims.find(s=>s.id===id);simT=0;document.querySelectorAll('[data-sim]').forEach(b=>b.classList.toggle('selected',b.dataset.sim===id));document.getElementById('sim-title').textContent=activeSim.name;document.getElementById('sim-kicker').textContent=activeSim.group;document.getElementById('sim-assumptions').textContent=activeSim.assume;document.getElementById('sim-overlay').textContent=activeSim.assume.toUpperCase();document.getElementById('sim-inputs').innerHTML=activeSim.fields.map(([id,n,v,u])=>`<div class="sim-input"><label for="si-${id}">${n}</label><input id="si-${id}" type="number" step="any" value="${v}"><span>${u}</span></div>`).join('');document.querySelectorAll('#sim-inputs input').forEach(i=>i.oninput=updateSim);updateSim()}
function simValues(){return Object.fromEntries(activeSim.fields.map(([id])=>[id,Number(document.getElementById('si-'+id).value)]))}function updateSim(){const x=simValues();let out;try{out=activeSim.calc(x)}catch{out=[]}document.getElementById('sim-results').innerHTML=out.map(([n,v,u])=>`<div class="result-row"><span>${n}</span><b>${sig(v)} ${u}</b></div>`).join('');drawSim()}
function drawSim(){const can=document.getElementById('sim-canvas');if(!can||!can.getBoundingClientRect().width)return;const r=can.getBoundingClientRect(),dpr=devicePixelRatio||1;can.width=r.width*dpr;can.height=r.height*dpr;const c=can.getContext('2d');c.scale(dpr,dpr);const w=r.width,h=r.height;c.clearRect(0,0,w,h);c.strokeStyle='#1c2b40';c.lineWidth=1;for(let x=20;x<w;x+=28){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()}for(let y=18;y<h;y+=28){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}const floor=h-30;c.strokeStyle='#39526f';c.beginPath();c.moveTo(20,floor);c.lineTo(w-18,floor);c.stroke();let stateFn=activeSim.path?.(simValues());if(stateFn){let T=stateFn(0).T||4,step=120;c.strokeStyle='#4d9df2';c.lineWidth=2;c.setLineDash([4,5]);c.beginPath();for(let i=0;i<=step;i++){let t=T*i/step,s=stateFn(t);let X=30+(s.x+4)/(8)*(w-60),Y=floor-((s.y||0)+.1)*(h-70)/4;if(i===0)c.moveTo(X,Y);else c.lineTo(X,Y)}c.stroke();c.setLineDash([]);const s=stateFn(simT%T),X=Math.max(20,Math.min(w-20,30+(s.x+4)/8*(w-60))),Y=Math.max(20,Math.min(floor-5,floor-((s.y||0)+.1)*(h-70)/4));c.fillStyle='#a27cff';c.shadowColor='#9c70ff';c.shadowBlur=15;c.beginPath();c.arc(X,Y,7,0,Math.PI*2);c.fill();c.shadowBlur=0}else{if(activeSim.id==='pressure'){for(let i=0;i<5;i++){c.fillStyle=`rgba(70,155,235,${.14+i*.09})`;c.fillRect(w*.23,floor-30-i*44,w*.55,42)}for(let i=0;i<3;i++){c.fillStyle='#85c5ff';c.beginPath();c.arc(w*.36+i*75,floor-65-i*39,4+i,0,Math.PI*2);c.fill()}}else if(activeSim.id==='circuit'){c.strokeStyle='#559cff';c.lineWidth=2;c.strokeRect(w*.26,h*.28,w*.46,h*.43);c.fillStyle='#13263e';c.fillRect(w*.43,h*.41,w*.13,h*.17);c.fillStyle='#9fcbff';c.font='11px DM Mono';c.fillText(`${simValues().V} V`,w*.46,h*.38);c.fillText(`${simValues().R} Ω`,w*.45,h*.52)}else if(activeSim.id==='hydraulic'){const x=simValues();c.fillStyle='#1b3857';c.fillRect(w*.25,h*.53,w*.5,h*.3);c.fillRect(w*.31,h*.32,w*.12,h*.22);c.fillRect(w*.6,h*.2,w*.22,h*.34);c.fillStyle='#79b9ff';c.fillRect(w*.31,h*.32,w*.12,7);c.fillRect(w*.6,h*.2,w*.22,7)}else{c.fillStyle='#172c43';c.beginPath();c.arc(w*.52,h*.53,35,0,Math.PI*2);c.fill()}}document.getElementById('sim-time').textContent=`t = ${simT.toFixed(2)} s`}
function playSim(){if(simTimer){clearInterval(simTimer);simTimer=null;document.getElementById('sim-play').innerHTML='▶ &nbsp;Run experiment';return}document.getElementById('sim-play').innerHTML='Ⅱ &nbsp;Pause';simTimer=setInterval(()=>{simT+=.04;drawSim()},40)}document.getElementById('sim-play').onclick=playSim;document.getElementById('sim-reset').onclick=()=>{simT=0;if(simTimer){clearInterval(simTimer);simTimer=null}document.getElementById('sim-play').innerHTML='▶ &nbsp;Run experiment';drawSim()};selectSim('projectile');
