let level='Basic',question=null,answered=0,correct=0,score=0,mode='numerical';const practiceBank=[
{cat:'Kinematics',level:'Basic',text:x=>`A cyclist travels at ${x.v} m/s for ${x.t} s at constant speed. How far do they travel?`,unit:'m',hint:'For constant speed, distance is speed multiplied by time.',make:()=>{let v=3+Math.floor(Math.random()*8),t=4+Math.floor(Math.random()*10);return{v,t,ans:v*t,eq:'d = vt',sub:`d = ${v} × ${t} = ${v*t} m`}}},
{cat:'Dynamics',level:'Basic',text:x=>`A ${x.m} kg cart accelerates at ${x.a} m/s². What is the net force?`,unit:'N',hint:'Use Newton’s second law: net force equals mass times acceleration.',make:()=>{let m=2+Math.floor(Math.random()*8),a=1+Math.floor(Math.random()*5);return{m,a,ans:m*a,eq:'F = ma',sub:`F = ${m} × ${a} = ${m*a} N`}}},
{cat:'Work & energy',level:'Intermediate',text:x=>`A ${x.m} kg ball moves at ${x.v} m/s. Find its kinetic energy.`,unit:'J',hint:'Kinetic energy depends on mass and the square of speed.',make:()=>{let m=1+Math.floor(Math.random()*5),v=2+Math.floor(Math.random()*8);return{m,v,ans:.5*m*v*v,eq:'K = ½mv²',sub:`K = ½ × ${m} × ${v}² = ${.5*m*v*v} J`}}},
{cat:'Thermodynamics',level:'Intermediate',text:x=>`A gas at ${x.P1} kPa occupies ${x.V1} L. At fixed temperature it is compressed to ${x.V2} L. Find the final pressure in kPa.`,unit:'kPa',hint:'At fixed temperature use P₁V₁ = P₂V₂.',make:()=>{let P1=100+Math.floor(Math.random()*101),V1=4+Math.floor(Math.random()*7),V2=2+Math.floor(Math.random()*3);return{P1,V1,V2,ans:P1*V1/V2,eq:'P₁V₁ = P₂V₂',sub:`P₂ = ${P1} × ${V1} / ${V2} = ${sig(P1*V1/V2)} kPa`}}},
{cat:'Waves',level:'Advanced',text:x=>`A wave has frequency ${x.f} Hz and wavelength ${x.l} m. Calculate its speed.`,unit:'m/s',hint:'Wave speed equals frequency multiplied by wavelength.',make:()=>{let f=20+Math.floor(Math.random()*100),l=+(.2+Math.floor(Math.random()*8)/10).toFixed(1);return{f,l,ans:+(f*l).toFixed(4),eq:'v = fλ',sub:`v = ${f} × ${l} = ${sig(f*l)} m/s`}}},
{cat:'Fluids',level:'Advanced',text:x=>`A ${x.rho} kg/m³ liquid is ${x.h} m deep. Find the gauge pressure at the bottom using g = 9.81 m/s².`,unit:'Pa',hint:'Hydrostatic gauge pressure is ρgh; use depth in metres.',make:()=>{let rho=[800,1000,1200][Math.floor(Math.random()*3)],h=2+Math.floor(Math.random()*9);return{rho,h,ans:rho*9.81*h,eq:'P = ρgh',sub:`P = ${rho} × 9.81 × ${h} = ${sig(rho*9.81*h)} Pa`}}},
{cat:'Concepts',level:'Basic',concept:true,text:'An object moves in a circle at constant speed. Which statement about its acceleration is correct?',choices:['It is zero because speed is constant.','It points toward the circle’s center.','It points tangent to the path.'],answer:1,hint:'Velocity changes direction even when its magnitude stays constant.',explain:'Centripetal acceleration points toward the center and changes the direction of velocity.'},
{cat:'Concepts',level:'Intermediate',concept:true,text:'A book rests on a table. Which pair forms an action–reaction pair?',choices:['Weight of the book and normal force on the book.','Book pushes down on table and table pushes up on book.','Weight of book and gravitational force of book on Earth.'],answer:1,hint:'Newton’s third-law forces act on two different objects.',explain:'The contact forces act on different bodies and are equal and opposite.'},
{cat:'Formula identification',level:'Basic',formula:true,text:'Which relationship gives the net force from mass and acceleration?',choices:['F = ma','P = IV','v = fλ'],answer:0,hint:'Think of Newton’s second law.',explain:'Newton’s second law states that net force equals mass times acceleration.'},
{cat:'Units',level:'Intermediate',units:true,text:'Convert 72 km/h to m/s.',choices:['20 m/s','25.9 m/s','7.2 m/s'],answer:0,hint:'Multiply km/h by 1000/3600.',explain:'72 × 1000 / 3600 = 20 m/s.'}
];
function newQuestion(){let pool=practiceBank.filter(q=>q.level===level&&((mode==='numerical'&&!q.concept&&!q.formula&&!q.units)||(mode==='concept'&&q.concept)||(mode==='formula'&&q.formula)||(mode==='units'&&q.units)));if(!pool.length)pool=practiceBank.filter(q=>(mode==='concept'&&q.concept)||(mode==='formula'&&q.formula)||(mode==='units'&&q.units)||(mode==='numerical'&&!q.concept&&!q.formula&&!q.units));let base=pool[Math.floor(Math.random()*pool.length)];question={...base,data:base.make?base.make():null};document.getElementById('question-category').textContent=question.cat.toUpperCase();document.getElementById('question-level').textContent=level.toUpperCase();{const qm=document.getElementById('question-mode');if(qm)qm.firstChild.nodeValue=({numerical:'NUMERICAL',concept:'CONCEPT',units:'UNITS',formula:'FORMULA'}[mode]||'NUMERICAL')+' · '}document.getElementById('session-level').textContent=level;document.getElementById('question-text').textContent=typeof base.text==='function'?base.text(question.data||{}):base.text;document.getElementById('answer-unit').textContent=base.unit||'choice';document.getElementById('answer-input').value='';delete document.getElementById('answer-input').dataset.choice;document.getElementById('answer-input').closest('label').style.display=base.choices?'none':'';document.getElementById('answer-input').required=!base.choices;document.querySelectorAll('#answer-form .choice-option').forEach(x=>x.remove());if(base.choices){document.getElementById('answer-form').insertAdjacentHTML('afterbegin',base.choices.map((c,i)=>`<button type="button" class="choice-option" data-choice="${i}">${String.fromCharCode(65+i)} &nbsp; ${c}</button>`).join(''));document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{document.getElementById('answer-input').dataset.choice=b.dataset.choice;document.querySelectorAll('[data-choice]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected')})}document.getElementById('hint-box').classList.add('hidden');document.getElementById('hint-box').textContent=base.hint||'';document.getElementById('hint-btn').classList.remove('hidden');document.getElementById('solution-box').classList.add('hidden');document.getElementById('answer-feedback').textContent='';document.getElementById('answer-input').disabled=false;document.querySelector('#answer-form button[type="submit"]').disabled=false;}
document.getElementById('difficulty-tabs').onclick=e=>{if(e.target.dataset.level){level=e.target.dataset.level;document.querySelectorAll('#difficulty-tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.level===level));newQuestion()}};document.getElementById('new-question').onclick=newQuestion;document.getElementById('hint-btn').onclick=()=>{document.getElementById('hint-box').classList.remove('hidden');document.getElementById('hint-btn').classList.add('hidden')};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=mode===b.dataset.mode?'numerical':b.dataset.mode;newQuestion();document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x.dataset.mode===mode))});
document.getElementById('answer-form').onsubmit=e=>{e.preventDefault();if(!question)return;let ok=false,explain='';if(question.choices){const sel=document.getElementById('answer-input').dataset.choice;if(sel===undefined){toast('Select an answer first');return}let choice=Number(sel);ok=choice===question.answer;explain=question.explain}else{let val=Number(document.getElementById('answer-input').value),expected=question.data.ans;ok=Number.isFinite(val)&&Math.abs(val-expected)<=Math.max(.02*Math.abs(expected),.01);explain=`${question.data.eq}: ${question.data.sub}`}answered++;if(ok){correct++;score+=level==='Basic'?1:level==='Intermediate'?2:3}document.getElementById('score').textContent=score;document.getElementById('answered-count').textContent=answered;document.getElementById('correct-count').textContent=correct;document.getElementById('accuracy').textContent=Math.round(100*correct/answered)+'%';document.querySelector('.progress-ring').style.background=`conic-gradient(#5b9ef1 ${360*correct/answered}deg,#1b2c43 0deg)`;document.getElementById('answer-feedback').innerHTML=ok?'<span style="color:#6addaa">✓ Correct. Nice reasoning.</span>':'<span style="color:#f19a92">Not quite. Review the solution below.</span>';document.getElementById('solution-box').innerHTML=`<strong>${ok?'Solution':'Worked solution'}</strong><br>${explain}`;document.getElementById('solution-box').classList.remove('hidden');document.getElementById('answer-input').disabled=true;document.querySelectorAll('.choice-option').forEach(b=>b.disabled=true);document.querySelector('#answer-form button[type="submit"]').disabled=true};newQuestion();
// Unit conversion catalog (SI-base factors, with offsets for temperatures).
const units={Speed:[['m/s',1,0],['km/h',1/3.6,0],['mph',0.44704,0]],Length:[['m',1,0],['km',1000,0],['cm',.01,0],['mm',.001,0],['ft',.3048,0]],Mass:[['kg',1,0],['g',.001,0],['mg',1e-6,0],['lb',.45359237,0]],Volume:[['m³',1,0],['cm³',1e-6,0],['L',.001,0],['mL',1e-6,0]],Density:[['kg/m³',1,0],['g/cm³',1000,0],['g/mL',1000,0]],Pressure:[['Pa',1,0],['kPa',1000,0],['bar',100000,0],['atm',101325,0],['mmHg',133.322387415,0]],Temperature:[['°C',1,273.15],['K',1,0],['°F',5/9,255.372222222]],Energy:[['J',1,0],['kJ',1000,0],['cal',4.184,0],['kWh',3600000,0],['eV',1.602176634e-19,0]],'Angular speed':[['rad/s',1,0],['rpm',2*Math.PI/60,0],['°/s',Math.PI/180,0]],Force:[['N',1,0],['kN',1000,0],['lbf',4.4482216153,0]],Time:[['s',1,0],['min',60,0],['h',3600,0],['ms',.001,0]]};
const typeSel=document.getElementById('convert-type'),fromSel=document.getElementById('convert-from'),toSel=document.getElementById('convert-to');typeSel.innerHTML=Object.keys(units).map(x=>`<option>${x}</option>`).join('');function updateUnits(){const list=units[typeSel.value];fromSel.innerHTML=list.map(u=>`<option>${u[0]}</option>`).join('');toSel.innerHTML=list.map(u=>`<option>${u[0]}</option>`).join('');if(list.length>1)toSel.selectedIndex=1;if(typeSel.value==='Speed'){fromSel.selectedIndex=1;toSel.selectedIndex=0}document.getElementById('convert-value').value=typeSel.value==='Speed'?72:typeSel.value==='Temperature'?20:1;convert()}function convert(){const list=units[typeSel.value],from=list.find(u=>u[0]===fromSel.value),to=list.find(u=>u[0]===toSel.value),v=Number(document.getElementById('convert-value').value);if(!Number.isFinite(v)||!from||!to)return;const base=v*from[1]+from[2],out=(base-to[2])/to[1];document.getElementById('conversion-output').textContent=`${sig(out,7)} ${to[0]}`;document.getElementById('conversion-detail').textContent=`${v} ${from[0]} → ${sig(base,6)} base units → ${sig(out,7)} ${to[0]}`};typeSel.onchange=updateUnits;fromSel.onchange=convert;toSel.onchange=convert;document.getElementById('convert-value').oninput=convert;updateUnits();document.getElementById('quick-conversions').innerHTML=[['72 km/h','20 m/s'],['1 g/cm³','1000 kg/m³'],['1 atm','101 325 Pa'],['0 °C','273.15 K'],['1 kWh','3.6 × 10⁶ J'],['60 rpm','2π rad/s']].map(x=>`<div class="quick-row"><span>${x[0]}</span><span>${x[1]}</span></div>`).join('');
function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
